<div class="management-grid"><section class="panel table-wrap"><h2>Additional navigation links</h2><p class="muted">News categories populate the primary navigation automatically.</p><table><thead><tr><th>Label</th><th>Destination</th><th>Active</th><th></th></tr></thead><tbody><?php foreach ($items as $row): ?><tr><td><?= e($row['name_en']) ?></td><td><?= e($row['url']) ?></td><td><?= $row['is_active'] ? 'Yes' : 'No' ?></td><td><a href="?edit=<?= (int)$row['id'] ?>">Edit</a></td></tr><?php endforeach ?></tbody></table></section><form method="post" class="panel form-stack"><?= csrf() ?><input type="hidden" name="id" value="<?= (int)($edit['id'] ?? 0) ?>"><h2><?= $edit ? 'Edit link' : 'Add link' ?></h2><?php foreach (['en'=>'English label','si'=>'Sinhala label','ta'=>'Tamil label'] as $l=>$label) $field('name_'.$l,$label,'text',null,'required maxlength="100"'); $field('url','Destination','text',null,'required placeholder="/classifieds"'); $field('order_index','Order','number',$edit['order_index'] ?? 0); ?><label class="check"><input type="checkbox" name="active" <?= ($edit['is_active'] ?? 1) ? 'checked' : '' ?>> Active</label><button class="button">Save link</button><a href="<?= e(url('admin/menus')) ?>">Clear form</a></form></div>
